B.abU=new A.lV(10,"\ud83e\udd49","Primi passi")
B.abV=new A.lV(50,"\ud83e\udd48","Lettore curioso")
B.abY=new A.lV(100,"\ud83e\udd47","Campione")
B.abZ=new A.lV(250,"\ud83c\udfc5","Super campione")
